type WorkspaceResponse struct {
	// Schema A URL to the JSON Schema for this object.
	Schema *string `json:"$schema,omitempty"`

	// AgentState Hook-reported aggregate state for live agent sessions. Omitted when no live session has reported lifecycle state.
	AgentState *WorkspaceResponseAgentState `json:"agent_state,omitempty"`

	// AgentStateUpdatedAt UTC timestamp of the hook report that produced agent_state.
	AgentStateUpdatedAt *time.Time `json:"agent_state_updated_at,omitempty"`
	AssociatedPrNumber  *int64     `json:"associated_pr_number,omitempty"`

	// BranchUpstreamMissing True when the current branch has an origin upstream configured but its local remote-tracking ref is absent; clients may offer Push so branch sync can verify or create the remote branch.
	BranchUpstreamMissing *bool        `json:"branch_upstream_missing,omitempty"`
	CommitAttribution     *Attribution `json:"commit_attribution,omitempty"`
	CommitsAhead          *int64       `json:"commits_ahead,omitempty"`
	CommitsBehind         *int64       `json:"commits_behind,omitempty"`

	// CommitsVsPrHead True when the current branch has no upstream and commits_ahead/commits_behind instead compare against the provider's locally fetched pull-request head ref, as for fork pull requests. The counts name no push or pull target, so clients must not offer branch sync for them.
	CommitsVsPrHead *bool `json:"commits_vs_pr_head,omitempty"`

	// Created True when this response represents a workspace newly created by this request; absent when an existing workspace was returned or on reads.
	Created   *bool  `json:"created,omitempty"`
	CreatedAt string `json:"created_at"`

	// EnrichmentError Combined error from the most recent reconciliation attempt; populated component fields may still contain last-known-good values.
	EnrichmentError *string `json:"enrichment_error,omitempty"`

	// EnrichmentRefreshedAt Oldest successful refresh time across the populated enrichment components.
	EnrichmentRefreshedAt *string `json:"enrichment_refreshed_at,omitempty"`

	// EnrichmentStatus Aggregate git-state and tmux-activity reconciliation status. Failed responses retain last-known-good component fields when available.
	EnrichmentStatus   WorkspaceResponseEnrichmentStatus `json:"enrichment_status"`
	ErrorMessage       *string                           `json:"error_message,omitempty"`
	GitHeadRef         string                            `json:"git_head_ref"`
	ID                 string                            `json:"id"`
	ItemKey            string                            `json:"item_key"`
	ItemLastActivityAt *string                           `json:"item_last_activity_at,omitempty"`
	ItemNumber         int64                             `json:"item_number"`
	ItemType           string                            `json:"item_type"`
	Kata               *WorkspaceKataMetadata            `json:"kata,omitempty"`
	MrAdditions        *int64                            `json:"mr_additions,omitempty"`
	MrCiStatus         *string                           `json:"mr_ci_status,omitempty"`
	MrDeletions        *int64                            `json:"mr_deletions,omitempty"`

	// MrHeadRepoKind Set only for pull_request workspaces: same_repo when the PR head is confirmed to be in the base repo, fork when it is a confirmed fork clone, unknown when repository identity could not be resolved.
	MrHeadRepoKind     *WorkspaceResponseMrHeadRepoKind `json:"mr_head_repo_kind,omitempty"`
	MrIsDraft          *bool                            `json:"mr_is_draft,omitempty"`
	MrReviewDecision   *string                          `json:"mr_review_decision,omitempty"`
	MrState            *string                          `json:"mr_state,omitempty"`
	MrTitle            *string                          `json:"mr_title,omitempty"`
	PlatformHost       string                           `json:"platform_host"`
	PushState          *PushState                       `json:"push_state,omitempty"`
	Repo               RepoRefResponse                  `json:"repo"`
	RepoName           string                           `json:"repo_name"`
	RepoOwner          string                           `json:"repo_owner"`
	Status             string                           `json:"status"`
	TmuxActivitySource string                           `json:"tmux_activity_source"`
	TmuxLastOutputAt   *string                          `json:"tmux_last_output_at,omitempty"`
	TmuxPaneTitle      *string                          `json:"tmux_pane_title,omitempty"`
	TmuxSession        string                           `json:"tmux_session"`
	TmuxWorking        bool                             `json:"tmux_working"`

	// WorktreeDirty True when the worktree has staged, unstaged, or untracked changes; false when clean; omitted until git-state enrichment completes.
	WorktreeDirty *bool  `json:"worktree_dirty,omitempty"`
	WorktreePath  string `json:"worktree_path"`
}

